CREATE TABLE users(id uuid PRIMARY KEY, username text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','manager','operator','quality','warehouse','viewer')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE records(id uuid PRIMARY KEY,resource text NOT NULL,code text NOT NULL,name text NOT NULL,status text NOT NULL,data jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1 CHECK(revision>0),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(resource,code));
CREATE INDEX records_lookup ON records(resource,status,created_at DESC);
CREATE TABLE record_references(record_id uuid NOT NULL REFERENCES records(id) ON DELETE CASCADE,field text NOT NULL,target_id uuid NOT NULL REFERENCES records(id) ON DELETE RESTRICT,PRIMARY KEY(record_id,field,target_id));
CREATE INDEX record_references_target ON record_references(target_id);
CREATE TABLE products(id uuid PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,unit text NOT NULL DEFAULT '件',safety_stock integer NOT NULL DEFAULT 0 CHECK(safety_stock>=0),active boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_steps(id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE,sequence integer NOT NULL CHECK(sequence>0),name text NOT NULL,unit_price numeric(18,4) NOT NULL CHECK(unit_price>=0),expected_minutes numeric(12,3) NOT NULL CHECK(expected_minutes>0),UNIQUE(product_id,sequence));
CREATE TABLE sales_orders(id uuid PRIMARY KEY,code text UNIQUE NOT NULL,customer_id uuid NOT NULL REFERENCES records(id) ON DELETE RESTRICT,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','complete','closed')),due_date date,notes text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sales_order_items(id uuid PRIMARY KEY,sales_order_id uuid NOT NULL REFERENCES sales_orders(id),product_id uuid NOT NULL REFERENCES products(id),quantity integer NOT NULL CHECK(quantity>0),unit_price numeric(18,4) NOT NULL DEFAULT 0 CHECK(unit_price>=0),UNIQUE(sales_order_id,product_id));
CREATE TABLE work_orders(id uuid PRIMARY KEY,code text UNIQUE NOT NULL,product_id uuid NOT NULL REFERENCES products(id),sales_order_id uuid REFERENCES sales_orders(id),quantity integer NOT NULL CHECK(quantity>0),good_quantity integer NOT NULL CHECK(good_quantity>=0 AND good_quantity<=quantity),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','working','complete','closed')),priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('normal','urgent')),due_date date,notes text NOT NULL DEFAULT '',close_reason text,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE INDEX work_orders_scope ON work_orders(product_id,sales_order_id,status);
CREATE TABLE tasks(id uuid PRIMARY KEY,work_order_id uuid NOT NULL REFERENCES work_orders(id),sequence integer NOT NULL,name text NOT NULL,unit_price numeric(18,4) NOT NULL CHECK(unit_price>=0),expected_minutes numeric(12,3) NOT NULL CHECK(expected_minutes>0),status text NOT NULL CHECK(status IN ('blocked','ready','received','working','complete')),completed_quantity integer NOT NULL DEFAULT 0 CHECK(completed_quantity>=0),UNIQUE(work_order_id,sequence));
CREATE TABLE reports(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES tasks(id),work_order_id uuid NOT NULL REFERENCES work_orders(id),worker_id uuid NOT NULL REFERENCES users(id),workstation_id uuid REFERENCES records(id),received_quantity integer NOT NULL CHECK(received_quantity>0),quantity integer NOT NULL DEFAULT 0 CHECK(quantity>=0 AND quantity<=received_quantity),status text NOT NULL CHECK(status IN ('received','working','complete','approved','rejected')),started_at timestamptz,completed_at timestamptz,approved_by uuid REFERENCES users(id),approved_at timestamptz,rejection_reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX reports_active_task ON reports(task_id) WHERE status IN ('received','working');
CREATE UNIQUE INDEX reports_active_station ON reports(workstation_id) WHERE status IN ('received','working') AND workstation_id IS NOT NULL;
CREATE UNIQUE INDEX reports_active_worker ON reports(worker_id) WHERE status IN ('received','working');
CREATE INDEX reports_work_order ON reports(work_order_id);
CREATE TABLE scraps(id uuid PRIMARY KEY,work_order_id uuid NOT NULL REFERENCES work_orders(id),task_id uuid REFERENCES tasks(id),report_id uuid REFERENCES reports(id),quantity integer NOT NULL CHECK(quantity>0),reason text NOT NULL,responsible_user_id uuid REFERENCES users(id),reported_by uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),approved_by uuid REFERENCES users(id),approved_at timestamptz,rejection_reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX scraps_work_order ON scraps(work_order_id,status);
CREATE TABLE stock_balances(id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES products(id),sales_order_id uuid REFERENCES sales_orders(id),in_quantity integer NOT NULL DEFAULT 0 CHECK(in_quantity>=0),out_quantity integer NOT NULL DEFAULT 0 CHECK(out_quantity>=0),quantity integer GENERATED ALWAYS AS(in_quantity-out_quantity) STORED CHECK(quantity>=0),UNIQUE NULLS NOT DISTINCT(product_id,sales_order_id));
CREATE TABLE stock_movements(id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES products(id),sales_order_id uuid REFERENCES sales_orders(id),direction text NOT NULL CHECK(direction IN ('in','out')),quantity integer NOT NULL CHECK(quantity>0),reason text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX movements_scope ON stock_movements(product_id,sales_order_id,created_at DESC);
CREATE TABLE payroll(id uuid PRIMARY KEY,worker_id uuid NOT NULL REFERENCES users(id),source_type text NOT NULL CHECK(source_type IN ('piece','hours','reward','penalty','scrap-penalty','scrap-reward')),source_id uuid NOT NULL,quantity numeric(18,4) NOT NULL CHECK(quantity>=0),unit_price numeric(18,4) NOT NULL CHECK(unit_price>=0),amount numeric(18,2) NOT NULL,work_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_type,source_id));
CREATE INDEX payroll_worker_date ON payroll(worker_id,work_date);
CREATE TABLE audit_logs(id uuid PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,resource text NOT NULL,resource_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_logs_created ON audit_logs(created_at DESC);
CREATE TABLE idempotency_keys(actor_id uuid NOT NULL REFERENCES users(id),scope text NOT NULL,request_id text NOT NULL,payload_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,scope,request_id));
CREATE UNIQUE INDEX records_device_no ON records((data->>'deviceNo')) WHERE resource='devices' AND coalesce(data->>'deviceNo','')<>'';
CREATE TABLE material_balances(material_id uuid PRIMARY KEY REFERENCES records(id),in_quantity numeric(18,4) NOT NULL DEFAULT 0 CHECK(in_quantity>=0),out_quantity numeric(18,4) NOT NULL DEFAULT 0 CHECK(out_quantity>=0),quantity numeric(18,4) GENERATED ALWAYS AS(in_quantity-out_quantity) STORED CHECK(quantity>=0));
CREATE TABLE material_movements(id uuid PRIMARY KEY,material_id uuid NOT NULL REFERENCES records(id),source_id uuid NOT NULL UNIQUE REFERENCES records(id),direction text NOT NULL CHECK(direction IN ('in','out')),quantity numeric(18,4) NOT NULL CHECK(quantity>0),created_at timestamptz NOT NULL DEFAULT now());
